//! Wire types shared by the Tauri backend and the Leptos webview. Everything here
//! crosses the IPC boundary as JSON, and `Settings` is also persisted as TOML.

use std::{fmt, path::PathBuf};

use serde::{Deserialize, Serialize};
use thiserror::Error;

/// Generated by the backend when an item is added. Not the video id, which is
/// unknown until metadata has been resolved.
pub type DownloadId = u64;

// ---------------------------------------------------------------------------
// Settings
// ---------------------------------------------------------------------------

pub const SETTINGS_VERSION: u32 = 3;
pub const MAX_CONCURRENT_DOWNLOADS: u8 = 5;

#[derive(Serialize, Deserialize, Debug, Clone, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct Settings {
    pub version: u32,
    pub output_dir: PathBuf,
    pub default_format: OutputFormat,
    pub theme: Theme,
    pub yt_dlp_channel: YtDlpChannel,
    pub max_concurrent_downloads: u8,
    pub embed_metadata: bool,
    pub notify_on_finish: bool,
    pub cookies_from_browser: Option<Browser>,
    pub language: Language,
}

impl Settings {
    /// Checks everything that does not need the filesystem. The backend also
    /// checks that `output_dir` is an existing directory.
    pub fn validate(&self) -> Result<(), String> {
        if self.version != SETTINGS_VERSION {
            return Err(format!(
                "settings version is {}, expected {SETTINGS_VERSION}",
                self.version
            ));
        }
        if !(1..=MAX_CONCURRENT_DOWNLOADS).contains(&self.max_concurrent_downloads) {
            return Err(format!(
                "max_concurrent_downloads is {}, expected 1 to {MAX_CONCURRENT_DOWNLOADS}",
                self.max_concurrent_downloads
            ));
        }
        if self.output_dir.as_os_str().is_empty() {
            return Err("output_dir is empty".to_string());
        }
        Ok(())
    }
}

#[derive(Serialize, Deserialize, Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum OutputFormat {
    Audio { codec: AudioCodec },
    Video { quality: VideoQuality },
}

impl OutputFormat {
    /// Part of the duplicate-detection key, together with extractor and video id.
    pub fn key(&self) -> String {
        match self {
            OutputFormat::Audio { codec } => format!("audio:{}", codec.as_str()),
            OutputFormat::Video { quality } => format!("video:{}", quality.as_str()),
        }
    }

    pub fn all() -> Vec<OutputFormat> {
        AudioCodec::ALL
            .into_iter()
            .map(|codec| OutputFormat::Audio { codec })
            .chain(
                VideoQuality::ALL
                    .into_iter()
                    .map(|quality| OutputFormat::Video { quality }),
            )
            .collect()
    }

    pub fn parse_key(key: &str) -> Option<OutputFormat> {
        OutputFormat::all().into_iter().find(|f| f.key() == key)
    }
}

impl fmt::Display for OutputFormat {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            OutputFormat::Audio { codec } => write!(f, "{} audio", codec.label()),
            OutputFormat::Video { quality } => write!(f, "MP4 video {}", quality.label()),
        }
    }
}

#[derive(Serialize, Deserialize, Debug, Clone, Copy, PartialEq, Eq, Hash)]
