#[derive(Serialize, Deserialize, Debug, Clone, PartialEq)]
pub struct VideoMetadata {
    /// yt-dlp's `extractor_key` (or `ie_key` for flat playlist entries), e.g. `Youtube`.
    pub extractor: String,
    pub video_id: String,
    pub title: String,
    pub uploader: Option<String>,
    pub duration_secs: Option<f64>,
    pub thumbnail: Option<String>,
    pub webpage_url: String,
}

impl VideoMetadata {
    /// Same video in the same output format means the same file.
    pub fn duplicate_key(&self, format: &OutputFormat) -> String {
        format!(
            "{}|{}|{}",
            self.extractor.to_lowercase(),
            self.video_id,
            format.key()
        )
    }
}

/// An earlier finished download of the same video in the same format whose file
/// still exists on disk.
#[derive(Serialize, Deserialize, Debug, Clone, PartialEq)]
pub struct PreviousDownload {
    pub finished_at_ms: i64,
    pub file_path: PathBuf,
}

#[derive(Serialize, Deserialize, Debug, Clone, PartialEq)]
pub struct DownloadItem {
    pub id: DownloadId,
    pub url: String,
    pub added_at_ms: i64,
    pub metadata: Option<VideoMetadata>,
    pub format: OutputFormat,
    /// File name without extension chosen by the user, validated with
    /// [`validate_file_stem`]. `None` uses the default `<title> [<id>]`.
    pub custom_name: Option<String>,
    pub status: DownloadStatus,
    pub previous_download: Option<PreviousDownload>,
    /// Final file, set once the item is `Finished`.
    pub file_path: Option<PathBuf>,
}

#[derive(Serialize, Deserialize, Debug, Clone, PartialEq)]
#[serde(tag = "state", rename_all = "snake_case")]
pub enum DownloadStatus {
    ResolvingMetadata,
    MetadataFailed {
        error: FriendlyError,
    },
    Ready,
    /// The user started a download that matches an earlier one; waits for
    /// `confirm_duplicate`.
    AwaitingDuplicateConfirmation,
    /// Waiting for a free concurrency slot.
    Queued,
    Downloading {
        progress: Progress,
    },
    /// ffmpeg post-processing (extract audio, merge, embed tags).
    Processing,
    Finished,
    Failed {
        error: FriendlyError,
    },
    Cancelled,
}

impl DownloadStatus {
    pub fn name(&self) -> &'static str {
        match self {
            DownloadStatus::ResolvingMetadata => "resolving metadata",
            DownloadStatus::MetadataFailed { .. } => "missing metadata",
            DownloadStatus::Ready => "ready",
            DownloadStatus::AwaitingDuplicateConfirmation => "awaiting confirmation",
            DownloadStatus::Queued => "queued",
            DownloadStatus::Downloading { .. } => "downloading",
            DownloadStatus::Processing => "processing",
            DownloadStatus::Finished => "finished",
            DownloadStatus::Failed { .. } => "failed",
            DownloadStatus::Cancelled => "cancelled",
        }
    }

    /// Holds a concurrency slot or is waiting for one. Cannot be removed or edited.
    pub fn is_active(&self) -> bool {
        matches!(
            self,
            DownloadStatus::Queued
                | DownloadStatus::Downloading { .. }
                | DownloadStatus::Processing
        )
    }

    pub fn can_start(&self) -> bool {
        matches!(self, DownloadStatus::Ready)
    }

    pub fn can_retry(&self) -> bool {
        matches!(
            self,
            DownloadStatus::Failed { .. }
                | DownloadStatus::Cancelled
                | DownloadStatus::MetadataFailed { .. }
        )
    }

    pub fn can_cancel(&self) -> bool {
        self.is_active() || matches!(self, DownloadStatus::AwaitingDuplicateConfirmation)
    }

    /// Format and name can change until the download starts.
    pub fn can_edit_before_download(&self) -> bool {
        matches!(
            self,
            DownloadStatus::Ready
                | DownloadStatus::MetadataFailed { .. }
                | DownloadStatus::Failed { .. }
                | DownloadStatus::Cancelled
        )
    }
}

