#[derive(Serialize, Deserialize, Debug, Clone, PartialEq)]
pub struct FriendlyError {
    pub kind: ErrorKind,
    /// One or two sentences for the user, including what to do next.
    pub message: String,
    /// Raw tail of yt-dlp's stderr or the underlying error, for "show details".
    pub detail: String,
}

#[derive(Serialize, Deserialize, Debug, Clone, Copy, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum ErrorKind {
    AgeRestricted,
    BotCheck,
    Private,
    Unavailable,
    GeoBlocked,
    RateLimited,
    Network,
    UnsupportedUrl,
    NotYetLive,
    DiskFull,
    /// The app exited while the download was running.
    Interrupted,
    /// The configured output folder does not exist. `detail` holds the path.
    OutputFolderMissing,
    /// A playlist resolved to no downloadable entries.
    EmptyPlaylist,
    Other,
}

impl ErrorKind {
    /// Errors that browser cookies (`cookies_from_browser`) usually fix.
    pub fn suggests_cookies(self) -> bool {
        matches!(
            self,
            ErrorKind::AgeRestricted | ErrorKind::BotCheck | ErrorKind::Private
        )
    }
}

#[derive(Serialize, Deserialize, Debug, Clone, PartialEq, Default)]
pub struct AddUrlsResult {
    pub added: Vec<DownloadId>,
    /// URLs already in the queue, skipped.
    pub already_queued: Vec<String>,
    /// Tokens that were not http(s) URLs.
    pub invalid: Vec<String>,
}

/// The playlist named by a link to a single video.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PlaylistLink {
    pub list_id: String,
    /// YouTube Mixes (`RD…`) are generated per viewer and have no playlist
    /// page, so they can only be expanded from a video link.
    pub is_mix: bool,
}

/// A YouTube link to one video that also names the playlist it was opened
/// from, e.g. `watch?v=X&list=Y`. yaydl adds only the video from such a link
/// until the user asks for the whole playlist (`expand_playlist`).
pub fn playlist_in_video_link(link: &str) -> Option<PlaylistLink> {
    let url = url::Url::parse(link).ok()?;
    let host = url.host_str()?;
    let host = host.strip_prefix("www.").unwrap_or(host);
    let query_value = |key: &str| {
        url.query_pairs()
            .find(|(k, v)| k == key && !v.is_empty())
            .map(|(_, v)| v.into_owned())
    };
    let names_video = match host {
        "youtube.com" | "m.youtube.com" | "music.youtube.com" => {
            url.path() == "/watch" && query_value("v").is_some()
        }
        "youtu.be" => url.path().len() > 1,
        _ => false,
    };
    if !names_video {
        return None;
    }
    let list_id = query_value("list")?;
    Some(PlaylistLink {
        is_mix: list_id.starts_with("RD"),
        list_id,
    })
}

const FORBIDDEN_FILE_CHARS: [char; 9] = ['/', '\\', ':', '*', '?', '"', '<', '>', '|'];
const RESERVED_WINDOWS_NAMES: [&str; 22] = [
    "CON", "PRN", "AUX", "NUL", "COM1", "COM2", "COM3", "COM4", "COM5", "COM6", "COM7", "COM8",
    "COM9", "LPT1", "LPT2", "LPT3", "LPT4", "LPT5", "LPT6", "LPT7", "LPT8", "LPT9",
];
pub const MAX_FILE_STEM_CHARS: usize = 200;

/// Validates a user-chosen file name without extension. Rejects rather than
/// rewrites, so the name on disk is exactly what the user typed. The rules are
/// the union of Linux and Windows restrictions, so a name valid here is valid
/// on both.
pub fn validate_file_stem(name: &str) -> Result<(), String> {
    if name.trim().is_empty() {
        return Err("the name is empty".to_string());
    }
    if name != name.trim() {
        return Err("the name starts or ends with whitespace".to_string());
    }
    if name.ends_with('.') {
        return Err("the name ends with a dot".to_string());
    }
    if name.chars().count() > MAX_FILE_STEM_CHARS {
        return Err(format!(
            "the name is longer than {MAX_FILE_STEM_CHARS} characters"
        ));
    }
    if let Some(c) = name
        .chars()
        .find(|c| FORBIDDEN_FILE_CHARS.contains(c) || c.is_control())
    {
        return Err(format!("the name contains the forbidden character {c:?}"));
    }
    let base = name.split('.').next().unwrap_or(name).to_ascii_uppercase();
    if RESERVED_WINDOWS_NAMES.contains(&base.as_str()) {
        return Err(format!("\"{name}\" is a reserved name on Windows"));
    }
    Ok(())
}

