#[derive(Serialize, Deserialize, Debug, Clone, Copy, PartialEq, Eq)]
#[serde(rename_all = "lowercase")]
pub enum NoticeLevel {
    Info,
    Success,
    Warning,
    Error,
}

/// A message the backend wants the user to see as a toast. Notices raised
/// before the webview called `take_startup_notices` are buffered and returned
/// by that call, later ones are emitted as the `notice` event.
#[derive(Serialize, Deserialize, Debug, Clone, PartialEq)]
pub struct Notice {
    pub level: NoticeLevel,
    pub text: String,
}

/// Event names emitted by the backend. Tauri wraps each payload in
/// `{ event, id, payload }`.
pub mod events {
    /// Payload `Vec<DownloadItem>`, the whole queue in display order. Sent on
    /// structural changes (add, remove, clear, playlist expansion).
    pub const QUEUE_REPLACED: &str = "queue-replaced";
    /// Payload `DownloadItem`. Sent when a single item changes, progress
    /// included, at most a few times per second per item.
    pub const QUEUE_ITEM_UPDATED: &str = "queue-item-updated";
    /// Payload `Notice`.
    pub const NOTICE: &str = "notice";
    /// Payload `AppUpdateProgress`.
    pub const APP_UPDATE_PROGRESS: &str = "app-update-progress";
    /// Payload `()`. Emitted when history changed (a download finished, a
    /// rename, or clear), so an open statistics view can reload.
    pub const HISTORY_CHANGED: &str = "history-changed";
}

